<section class="nl-surface overflow-hidden"><div class="border-b border-border px-5 py-4"><h2 class="font-bold text-foreground">{{ $title }}</h2><p class="mt-1 text-xs text-muted">{{ count($rows) }} baris data</p></div>@if (count($rows))<div class="overflow-x-auto"><table class="min-w-[720px] w-full text-left text-sm"><thead class="border-b border-border bg-background text-xs uppercase tracking-wider text-muted"><tr>@foreach ($columns as $key => $label)<th class="px-5 py-3 {{ in_array($key, $moneyKeys, true) || in_array($key, ['transactions', 'quantity', 'count', 'percentage'], true) ? 'text-right' : '' }}">{{ $label }}</th>@endforeach</tr></thead><tbody class="divide-y divide-border">@foreach ($rows as $row)<tr class="hover:bg-background">@foreach ($columns as $key => $label)<td class="px-5 py-3 {{ in_array($key, $moneyKeys, true) || in_array($key, ['transactions', 'quantity', 'count', 'percentage'], true) ? 'text-right font-semibold' : 'text-secondary' }}">@if (in_array($key, $moneyKeys, true)){{ $money($row[$key] ?? 0) }}@elseif (in_array($key, $dateKeys, true)){{ $date($row[$key] ?? null) }}@elseif ($key === 'percentage'){{ $row[$key] ?? 0 }}%@else{{ $row[$key] ?? '-' }}@endif</td>@endforeach</tr>@endforeach</tbody></table></div>@else<div class="px-5 py-12 text-center text-sm text-muted">Tidak ada data pada periode ini.</div>@endif</section>
